package com.examforge.user;
import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;import com.baomidou.mybatisplus.extension.plugins.pagination.Page;import com.examforge.common.*;import com.examforge.common.ApiDtos.*;import com.examforge.security.JwtService;import com.examforge.user.entity.UserEntity;import com.examforge.user.mapper.UserMapper;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.time.LocalDateTime;import java.util.Locale;
@Service public class UserService{
 private final UserMapper mapper;private final PasswordEncoder encoder;private final JwtService jwt;public UserService(UserMapper m,PasswordEncoder e,JwtService j){mapper=m;encoder=e;jwt=j;}
 public LoginResponse login(LoginRequest r){UserEntity u=mapper.selectByUsername(r.username());if(u==null||u.getStatus()==0||!encoder.matches(r.password(),u.getPassword()))throw new BusinessException(401,"用户名或密码错误");return new LoginResponse(jwt.generate(u),u.getId(),u.getUsername(),u.getDisplayName(),u.getRole());}
 public UserView create(CreateUserRequest r){String role=r.role().toUpperCase(Locale.ROOT);if(!role.matches("ADMIN|TEACHER|STUDENT"))throw new BusinessException("角色仅支持 ADMIN、TEACHER、STUDENT");UserEntity u=new UserEntity();u.setUsername(r.username());u.setPassword(encoder.encode(r.password()));u.setDisplayName(r.displayName());u.setRole(role);u.setStatus(1);u.setCreateTime(LocalDateTime.now());u.setUpdateTime(LocalDateTime.now());mapper.insert(u);return view(u);}
 public PageView<UserView> page(long page,long size){Page<UserEntity>p=mapper.selectPage(new Page<>(page,size),new LambdaQueryWrapper<UserEntity>().orderByDesc(UserEntity::getId));return new PageView<>(p.getRecords().stream().map(this::view).toList(),p.getTotal(),p.getCurrent(),p.getSize());}
 @Transactional public void setStatus(Long id,Integer status){UserEntity u=mapper.selectById(id);if(u==null)throw new BusinessException("用户不存在");u.setStatus(status);u.setUpdateTime(LocalDateTime.now());mapper.updateById(u);}
 private UserView view(UserEntity u){return new UserView(u.getId(),u.getUsername(),u.getDisplayName(),u.getRole(),u.getStatus(),u.getCreateTime());}
}
